// [RADAR_HUB] - Motor Avançado de Cálculo de Margem e Custos Ocultos
const items = $input.all();
return items.map(item => {
  let data = item.json;
  let netProfit = 0;
  let evaluationScore = data.evaluation_score || 50;

  if (data.category === 'car_auction') {
    const lance = parseFloat(data.opportunity_price) || 0;
    const fipe = parseFloat(data.fipe_or_market_ref) || 0;
    const taxaLeiloeiro = lance * 0.05;
    const taxasPatioGuincho = 900.00;
    const custoTotalAquisicao = lance + taxaLeiloeiro + taxasPatioGuincho;
    netProfit = fipe - custoTotalAquisicao;

    // Recalcula score baseado no deságio real pós-taxas
    const desagioReal = (fipe - custoTotalAquisicao) / fipe;
    if (desagioReal > 0.40) evaluationScore = 95;
    else if (desagioReal > 0.25) evaluationScore = 80;
    else evaluationScore = 50;

  } else if (data.category === 'price_bug') {
    const precoAtual = parseFloat(data.opportunity_price) || 0;
    const precoMedio = parseFloat(data.original_price) || 1;
    const desconto = 1 - (precoAtual / precoMedio);
    netProfit = precoMedio - precoAtual;

    if (desconto >= 0.60) evaluationScore = 98;
    else if (desconto >= 0.40) evaluationScore = 85;
  }

  data.net_profit_estimate = parseFloat(netProfit.toFixed(2));
  data.evaluation_score = evaluationScore;

  return { json: data };
});
